package com.bananalab.lite;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class Stage40CoreCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static BananaEngine.Result run(CreatorPersistenceCheck.Fake c,Semilla m,String s)throws Exception{return BananaEngine.run(c,s,new ArrayList<String[]>(),"",true,m);}
 public static void main(String[] args)throws Exception{String r=args[0];MobileKnowledge.model=new ContextEncoder(new FileInputStream(r+"/assets/mobilecore1/mobilecore1.bin"),new String(Files.readAllBytes(Paths.get(r+"/assets/mobilecore1/labels.txt")),"UTF-8").trim().split("\\n"));MobileKnowledge.lessons=new JSONArray(new String(Files.readAllBytes(Paths.get(r+"/assets/mobilecore1/lessons.json")),"UTF-8"));CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();Semilla m=SemillaCheck.load(r+"/assets/language");
  BananaEngine.Result out=run(c,m,"que es un algoritmo");check(out.mode.equals("conocimiento_local")&&out.text.contains("instrucciones"),"own neural offline knowledge");out=run(c,m,"dame un ejemplo");check(out.text.contains("ordenar tres números"),"topic survives example followup");out=run(c,m,"explicalo paso a paso");check(out.text.contains("1. Definí"),"steps selected from same lesson");run(c,m,"modo breve");out=run(c,m,"que es un algoritmo");check(!out.text.contains("Ejemplo:"),"persistent brief style");run(c,m,"modo detallado");out=run(c,m,"que es una variable");check(out.text.contains("Ejemplo:")&&out.text.contains("Por qué importa:"),"detailed local explanation");
  out=run(c,m,"planea: crea a Tony una banana detective; agrega un pepino llamado Milo; Tony baila; Milo entra por la derecha; Tony dice \"Hola; vamos.\"");check(out.text.contains("5 pasos")&&SceneStore.load(c)==null,"quoted semicolon and preview isolated");out=run(c,m,"aplica el plan");check(out.changed&&out.scene.cast.size()==2&&out.scene.dialogue.size()==1&&out.scene.dialogue.get(0).text.contains("Hola;"),"atomic plan retains quotes actors and dialogue");check(out.scene.actions.contains("baila")&&out.scene.actions.contains("entrader"),"ordered actions preserved");
  out=run(c,m,"no, el que entra tiene que ser azul");check(out.changed&&out.scene.get("pepino").look.contains("azul")&&!out.scene.get("banana").look.contains("azul"),"event-role correction touches incoming actor");out=run(c,m,"por que hiciste eso");check(out.text.contains("Tu pedido fue:")&&ChatLanguage.normalize(out.text).contains("milo"),"grounded operational explanation");String before=SceneStore.load(c).json().toString();out=run(c,m,"primero pone a Tony rojo despues hace que un dragon vuele");check(!out.changed&&before.equals(SceneStore.load(c).json().toString())&&out.text.contains("Paso 2"),"failed multi-task is atomic");out=run(c,m,"corrige paso 2: continua con Milo saluda");check(out.text.contains("No lo apliqué"),"repair failed plan step");out=run(c,m,"aplica el plan");check(out.changed&&out.scene.get("banana").look.contains("rojo")&&out.scene.actions.contains("saluda"),"repaired plan commits together");
  run(c,m,"planea: pone a Tony verde; continua con Milo salta");run(c,m,"pone a Tony amarillo");before=SceneStore.load(c).json().toString();out=run(c,m,"aplica el plan");check(!out.changed&&before.equals(SceneStore.load(c).json().toString())&&out.text.contains("cambió"),"stale plan blocked");
  run(c,m,"cuando diga \"fiesta verde\" quiero decir \"pone a Tony verde\"");out=run(c,m,"fiesta verde");check(out.changed&&out.scene.get("banana").look.contains("verde"),"explicit taught phrase persists and executes");run(c,m,"olvida la frase fiesta verde");check(MobileCore.aliases(c).length()==0,"selective phrase deletion");run(c,m,"eso no responde mi pregunta");check(MobileCore.prefs(c).getBoolean("repair",false),"feedback does not silently approve answer");run(c,m,"anota esta correccion: la pregunta era sobre otro personaje");check(new JSONArray(MobileCore.prefs(c).getString("feedback","[]")).length()==1,"feedback saved as user data");
  JSONArray fixtures=new JSONArray(new String(Files.readAllBytes(Paths.get(r+"/test/resources/mobilecore1-parity.json")),"UTF-8"));double error=0;for(int i=0;i<fixtures.length();i++){JSONObject row=fixtures.getJSONObject(i);float[] got=MobileKnowledge.model.forward(ContextEncoder.features(row.getString("q")));JSONArray expected=row.getJSONArray("logits");for(int k=0;k<got.length;k++)error=Math.max(error,Math.abs(got[k]-expected.getDouble(k)));}check(error<.00003,"own topic router Java/Python parity");JSONArray held=new JSONObject(new String(Files.readAllBytes(Paths.get(r+"/assets/mobilecore1/model-card.json")),"UTF-8")).getJSONArray("heldout");int accepted=0,correct=0;for(int i=0;i<held.length();i++){JSONObject row=held.getJSONObject(i);String selected=MobileKnowledge.select(c,row.getString("q"));if(!selected.isEmpty()){accepted++;if(selected.equals(row.getString("expected")))correct++;}}check(accepted>=45&&accepted==correct,"runtime gate heldout precision and coverage");System.out.println("Runtime selected "+accepted+"/"+held.length()+", correct "+correct);System.out.println("PASS Stage40 offline own neural retrieval, followups, styles, atomic quote-aware plans, role correction, explanation, plan repair, stale guard, taught phrases, feedback and model parity "+error);
 }
}
